#!/usr/bin/env python3
"""Read-only figure manifest viewer; figures are generated by compute_v2_metrics.py."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]

if __name__ == "__main__":
    print(json.dumps(json.loads((ROOT / "figure_manifests/FIGURE_MANIFEST.json").read_text()), indent=2))
